01-spectra-and-density/density-noise.src:
// density-noise.js — scanner noise in transmittance mapped to density, and two ways to estimate its σ.
// Model: samples T + n with n ~ N(0, σ_T), a fraction p replaced by dust outliers T·U(0.3, 0.8); D = −log10 max(t, 1e−6).
// Left: histogram of one patch's densities with the theory σ_T/(T ln 10), the standard deviation and
// 1.4826·MAD. Right: σ_D against D for the same σ_T and p, seeded (mulberry32). Try: raise the contamination from 0
// to 10 %, then lower T (raise D) past 2 and watch the first-order law fail.
exports.meta = {
  title: 'Density noise and the MAD', chapter: '1',
  about: 'Density noise is σ_T / (T ln 10): it grows as the film gets denser, and the MAD measures it through outliers.',
  size: [640, 360],
  params: {
    D: { value: 1.0, min: 0, max: 2.6, step: 0.05, label: 'patch density D = −log10 T' },
    sigmaT: { value: 0.002, min: 0.0005, max: 0.01, step: 0.0005, label: 'transmittance noise σ_T' },
    p: { value: 0.05, min: 0, max: 0.3, step: 0.01, label: 'outlier fraction p' },
    n: { value: 2000, min: 200, max: 5000, step: 100, label: 'samples per patch' },
    seed: { value: 1, min: 1, max: 50, step: 1, label: 'seed' },
  },
};
const INK = '#1a1a1a', MUT = '#737373', HAIR = '#d6d6d6', ACC = '#e2001a', LN10 = Math.log(10);
function mulberry32(a) { return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function samples(rnd, D0, sT, p, n) {
  const T = Math.pow(10, -D0), out = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const g = Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
    let t = T + sT * g; if (rnd() < p) t = T * (0.3 + 0.5 * rnd());
    out[i] = -Math.log10(Math.max(t, 1e-6));
  }
  return out;
}
const median = (a) => { const s = Float64Array.from(a).sort(); return s.length % 2 ? s[s.length >> 1] : 0.5 * (s[s.length / 2 - 1] + s[s.length / 2]); };
const mad = (a) => { const m = median(a); return 1.4826 * median(a.map((v) => Math.abs(v - m))); };
const std = (a) => { const m = a.reduce((s, v) => s + v, 0) / a.length; return Math.sqrt(a.reduce((s, v) => s + (v - m) ** 2, 0) / (a.length - 1)); };
exports.setup = ({ params }) => {
  const rnd = mulberry32(params.seed * 9973);
  const x = samples(rnd, params.D, params.sigmaT, params.p, params.n);
  const sweep = [];
  for (let D0 = 0; D0 <= 2.601; D0 += 0.2) { const s = samples(rnd, D0, params.sigmaT, params.p, 800); sweep.push({ D: D0, sd: std(s), mad: mad(s) }); }
  return { x, sd: std(x), mad: mad(x), med: median(x), mean: x.reduce((s, v) => s + v, 0) / x.length, th: params.sigmaT / (Math.pow(10, -params.D) * LN10), sweep };
};
exports.draw = (ctx, { w, h, params, state: S }) => {
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); ctx.font = '11px Arial';
  // histogram
  const lo = params.D - 6 * S.th, hi = params.D + 6 * S.th, nb = 48, cnt = new Array(nb).fill(0); let below = 0, above = 0;
  for (const v of S.x) { const b = Math.floor((v - lo) / (hi - lo) * nb); if (b < 0) below++; else if (b >= nb) above++; else cnt[b]++; }
  const x0 = 40, y0 = 40, W = 270, H = 230, cm = Math.max(...cnt), X = (v) => x0 + (v - lo) / (hi - lo) * W;
  ctx.fillStyle = '#e6e6e6'; cnt.forEach((c, b) => { const bh = c / cm * H; ctx.fillRect(x0 + b * W / nb, y0 + H - bh, W / nb - 0.5, bh); });
  ctx.strokeStyle = MUT; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x0, y0 + H); ctx.lineTo(x0 + W, y0 + H); ctx.stroke();
  ctx.fillStyle = MUT; ctx.textAlign = 'center'; [lo, params.D, hi].forEach((v) => ctx.fillText(v.toFixed(3), X(v), y0 + H + 14));
  ctx.fillText('density of each sample (±6σ shown)', x0 + W / 2, y0 + H + 30);
  ctx.textAlign = 'right'; ctx.fillText(`beyond the right edge: ${above}, left: ${below}`, x0 + W, y0 + 66);
  const cl = (v) => Math.max(x0, Math.min(x0 + W, v));
  const bar = (c, s, y, col, dash, lab) => { ctx.strokeStyle = col; ctx.lineWidth = 1.6; ctx.setLineDash(dash); ctx.beginPath(); ctx.moveTo(cl(X(c - s)), y); ctx.lineTo(cl(X(c + s)), y); ctx.stroke(); ctx.setLineDash([]); ctx.fillStyle = col; ctx.textAlign = 'right'; ctx.fillText(lab, x0 + W, y - 3); };
  bar(params.D, S.th, y0 + 4, INK, [], 'theory ±σ');
  bar(S.med, S.mad, y0 + 26, ACC, [], 'median ±MAD·1.4826');
  bar(S.mean, S.sd, y0 + 48, MUT, [4, 3], 'mean ±std');
  ctx.fillStyle = INK; ctx.textAlign = 'left';
  ctx.fillText(`T = ${Math.pow(10, -params.D).toFixed(4)}   σ_T / (T ln 10) = ${S.th.toFixed(4)}`, x0, 20);
  ctx.fillStyle = ACC; ctx.fillText(`MAD estimate ${S.mad.toFixed(4)}`, x0, y0 + H + 52);
  ctx.fillStyle = MUT; ctx.fillText(`standard deviation ${S.sd.toFixed(4)}`, x0 + 140, y0 + H + 52);
  // sigma vs D
  const a0 = 400, b0 = 30, AW = 220, AH = 250, ylo = Math.log10(2e-4), yhi = Math.log10(3);
  const XX = (v) => a0 + v / 2.6 * AW, YY = (v) => b0 + AH - (Math.log10(Math.max(v, 1e-6)) - ylo) / (yhi - ylo) * AH;
  ctx.strokeStyle = MUT; ctx.beginPath(); ctx.moveTo(a0, b0); ctx.lineTo(a0, b0 + AH); ctx.lineTo(a0 + AW, b0 + AH); ctx.stroke();
  ctx.fillStyle = MUT; ctx.textAlign = 'right'; [0.001, 0.01, 0.1, 1].forEach((v) => ctx.fillText(String(v), a0 - 4, YY(v) + 4));
  ctx.textAlign = 'center'; [0, 1, 2].forEach((v) => ctx.fillText(String(v), XX(v), b0 + AH + 14)); ctx.fillText('density D', a0 + AW / 2, b0 + AH + 30);
  ctx.strokeStyle = INK; ctx.lineWidth = 1.4; ctx.beginPath();
  for (let i = 0; i <= 52; i++) { const D0 = 2.6 * i / 52, v = params.sigmaT * Math.pow(10, D0) / LN10; i ? ctx.lineTo(XX(D0), YY(v)) : ctx.moveTo(XX(D0), YY(v)); } ctx.stroke();
  for (const r of S.sweep) {
    ctx.fillStyle = INK; ctx.beginPath(); ctx.arc(XX(r.D), YY(r.mad), 2.6, 0, 7); ctx.fill();
    ctx.strokeStyle = INK; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(XX(r.D), YY(r.sd), 3.2, 0, 7); ctx.stroke();
  }
  ctx.strokeStyle = ACC; ctx.lineWidth = 1; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(XX(params.D), b0); ctx.lineTo(XX(params.D), b0 + AH); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = MUT; ctx.textAlign = 'left'; ctx.font = '10px Arial'; ctx.fillText('σ OF D: LINE = LAW, ● MAD, ○ STD', a0 - 30, 20);
  ctx.font = '11px Arial'; ctx.fillText(`outliers p = ${(100 * params.p).toFixed(0)} %, σ_T = ${params.sigmaT}`, a0 - 30, b0 + AH + 52);
};

