// curve-explorer.js — spektrafilm's parametric characteristic curve over Portra 400's tabulated dye amounts.
// f(x) = dmin + γ·t·log10(1 + 10^((x − x0)/t)) − γ·s·log10(1 + 10^((x − x0 − D/γ)/s))  (model/parametric.py, stock.js).
// Parameters: the layer, γ, x0, D (dmax), toe t and shoulder s; a density whose inverse is found by Newton's method.
// Starts at the least-squares fit of the chosen layer. Try: toe 0.10 (the broken line), or move the inverse density
// into the toe and watch the slope, and so the noise gain 1/f', change. Film data: spektrafilm (CC BY-SA 4.0).
const DATA = {"logE":[-3.0,-2.8902,-2.7804,-2.6706,-2.5608,-2.451,-2.3412,-2.2314,-2.1216,-2.0118,-1.902,-1.7922,-1.6824,-1.5725,-1.4627,-1.3529,-1.2431,-1.1333,-1.0235,-0.9137,-0.8039,-0.6941,-0.5843,-0.4745,-0.3647,-0.2549,-0.1451,-0.0353,0.0745,0.1843,0.2941,0.4039,0.5137,0.6235,0.7333,0.8431,0.9529,1.0627,1.1725,1.2824,1.3922,1.502,1.6118,1.7216,1.8314,1.9412,2.051,2.1608,2.2706,2.3804,2.4902,2.6,2.7098,2.8196,2.9294,3.0392,3.149,3.2588,3.3686,3.4784,3.5882,3.698,3.8078,3.9176,4.0],"curves":[[-0.0007,-0.0001,0.0003,0.0003,-0.0001,0.0003,0.0002,-0.0001,0.0005,0.001,0.0024,0.0045,0.0094,0.0156,0.0275,0.0442,0.0705,0.1027,0.1453,0.1969,0.2546,0.3182,0.3819,0.4414,0.5047,0.5598,0.6103,0.6685,0.7198,0.7739,0.8323,0.8946,0.9538,1.0223,1.085,1.1468,1.2093,1.2717,1.336,1.3995,1.4616,1.5319,1.593,1.6583,1.7198,1.771,1.8247,1.8616,1.902,1.9272,1.9488,1.962,1.974,1.9807,1.9846,1.9878,1.9887,1.9899,1.9902,1.9906,1.9909,1.9902,1.991,1.9905,1.9904],[-0.0007,-0.0,0.0001,0.0001,-0.0,0.0003,0.0,0.0006,0.001,0.0027,0.004,0.0091,0.0156,0.0269,0.0444,0.0675,0.1036,0.1444,0.1899,0.2489,0.3065,0.3661,0.4263,0.4824,0.5364,0.5881,0.6386,0.687,0.7415,0.7937,0.8455,0.9061,0.9573,1.0183,1.0725,1.1309,1.1821,1.2339,1.2902,1.3462,1.4025,1.4615,1.5157,1.5665,1.6153,1.6556,1.6938,1.7222,1.7457,1.7632,1.7749,1.7829,1.7898,1.7937,1.7951,1.7961,1.7969,1.7977,1.7978,1.7977,1.7975,1.7981,1.7974,1.798,1.7982],[-0.0007,-0.0001,0.0003,-0.0,0.0003,0.0003,0.0004,0.0012,0.0025,0.0048,0.0089,0.017,0.0283,0.0474,0.0748,0.1113,0.156,0.2101,0.2757,0.3416,0.4118,0.4833,0.5466,0.6097,0.6716,0.7262,0.7848,0.8454,0.9044,0.9715,1.036,1.1058,1.1743,1.2355,1.3013,1.3679,1.428,1.4907,1.5565,1.6229,1.6872,1.7595,1.8269,1.8882,1.9451,1.9965,2.04,2.0743,2.102,2.1217,2.1368,2.1471,2.1529,2.1571,2.1587,2.161,2.1619,2.1619,2.1624,2.1621,2.1623,2.1628,2.1627,2.1624,2.1621]],"fits":[{"gamma":0.5572,"x0":-1.2359,"dmax":1.9883,"toe":0.4555,"shoulder":0.3865,"dmin":-0.0016},{"gamma":0.5005,"x0":-1.4103,"dmax":1.7943,"toe":0.3349,"shoulder":0.4519,"dmin":0.002},{"gamma":0.5864,"x0":-1.488,"dmax":2.1577,"toe":0.36,"shoulder":0.4101,"dmin":0.0019}]};
exports.meta = {
  title: 'The characteristic curve', chapter: '2', size: [640, 360],
  about: 'The two-softplus curve, its slope and its inverse, against Portra 400 data.',
  params: {
    layer: { value: 'M', options: ['C', 'M', 'Y'], label: 'layer' },
    gamma: { value: 0.501, min: 0.2, max: 1.2, step: 0.001, label: 'gamma γ' },
    x0: { value: -1.41, min: -3, max: 0, step: 0.01, label: 'toe corner x0' },
    dmax: { value: 1.794, min: 0.5, max: 3, step: 0.01, label: 'range D' },
    toe: { value: 0.34, min: 0.02, max: 1, step: 0.01, label: 'toe t' },
    shoulder: { value: 0.45, min: 0.02, max: 1, step: 0.01, label: 'shoulder s' },
    invD: { value: 0.7, min: 0.02, max: 2.0, step: 0.01, label: 'inverse at density' },
  },
};
const sp = (u, s) => { const z = u / s; return s * (Math.max(z, 0) + Math.log10(1 + Math.pow(10, -Math.abs(z)))); };
const L = (z) => 1 / (1 + Math.pow(10, -z));
const f = (x, p) => p.dmin + p.gamma * sp(x - p.x0, p.toe) - p.gamma * sp(x - p.x0 - p.dmax / p.gamma, p.shoulder);
const df = (x, p) => p.gamma * (L((x - p.x0) / p.toe) - L((x - p.x0 - p.dmax / p.gamma) / p.shoulder));
function inverse(y, p) {
  let lo = -20, hi = 20, x = p.x0 + (y - p.dmin) / p.gamma;
  for (let i = 0; i < 60; i++) {
    const r = f(x, p) - y; if (r < 0) lo = x; else hi = x;
    let xn = x - r / Math.max(df(x, p), 1e-300); if (!(xn > lo && xn < hi)) xn = 0.5 * (lo + hi); x = xn;
  }
  return x;
}
exports.setup = ({ params }) => {
  const k = 'CMY'.indexOf(params.layer), fit = DATA.fits[k];
  const p = { gamma: params.gamma, x0: params.x0, dmax: params.dmax, toe: params.toe, shoulder: params.shoulder, dmin: fit.dmin };
  // residual against the table on −2.5…3.5
  let se = 0, n = 0; DATA.logE.forEach((x, i) => { if (x >= -2.5 && x <= 3.5) { se += (f(x, p) - DATA.curves[k][i]) ** 2; n++; } });
  const yi = Math.min(params.invD, p.dmin + p.dmax - 1e-4), xi = inverse(yi, p);
  return { k, p, rms: Math.sqrt(se / n), yi, xi, si: df(xi, p) };
};
exports.draw = (ctx, { w, h, state: S }) => {
  const ink = '#1a1a1a', mut = '#737373', hair = '#d6d6d6', red = '#e2001a';
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); ctx.font = '11px Arial';
  const A = { x0: 52, y0: 20, w: 360, h: 270, xl: [-3, 4], yl: [0, 2.4] };
  const B = { x0: 470, y0: 20, w: 150, h: 120, xl: [-3, 4], yl: [0, 1.0] };
  const X = (P, x) => P.x0 + (x - P.xl[0]) / (P.xl[1] - P.xl[0]) * P.w, Y = (P, y) => P.y0 + P.h - (y - P.yl[0]) / (P.yl[1] - P.yl[0]) * P.h;
  const axes = (P, xt, yt, xlab, ylab) => {
    ctx.strokeStyle = hair; ctx.lineWidth = 1; yt.forEach((t) => { ctx.beginPath(); ctx.moveTo(P.x0, Y(P, t)); ctx.lineTo(P.x0 + P.w, Y(P, t)); ctx.stroke(); });
    ctx.strokeStyle = mut; ctx.beginPath(); ctx.moveTo(P.x0, P.y0); ctx.lineTo(P.x0, P.y0 + P.h); ctx.lineTo(P.x0 + P.w, P.y0 + P.h); ctx.stroke();
    ctx.fillStyle = mut; ctx.textAlign = 'center'; xt.forEach((t) => ctx.fillText(String(t).replace('-', '−'), X(P, t), P.y0 + P.h + 14));
    ctx.textAlign = 'right'; yt.forEach((t) => ctx.fillText(String(t), P.x0 - 5, Y(P, t) + 4));
    ctx.textAlign = 'center'; ctx.fillText(xlab, P.x0 + P.w / 2, P.y0 + P.h + 30);
    ctx.save(); ctx.translate(P.x0 - 34, P.y0 + P.h / 2); ctx.rotate(-Math.PI / 2); ctx.fillText(ylab, 0, 0); ctx.restore();
  };
  const line = (P, fn, color, width, dash) => { ctx.strokeStyle = color; ctx.lineWidth = width; ctx.setLineDash(dash || []); ctx.beginPath(); for (let i = 0; i <= 280; i++) { const x = P.xl[0] + (P.xl[1] - P.xl[0]) * i / 280, y = Math.min(P.yl[1], Math.max(P.yl[0], fn(x))); i ? ctx.lineTo(X(P, x), Y(P, y)) : ctx.moveTo(X(P, x), Y(P, y)); } ctx.stroke(); ctx.setLineDash([]); };
  const p = S.p;
  axes(A, [-3, -2, -1, 0, 1, 2, 3, 4], [0, 0.5, 1, 1.5, 2], 'log H (grey card = 0)', 'dye amount');
  // the broken line and its corners
  const xc = p.x0 + p.dmax / p.gamma;
  ctx.strokeStyle = red; ctx.lineWidth = 1; ctx.setLineDash([4, 3]); ctx.beginPath(); ctx.moveTo(X(A, -3), Y(A, p.dmin)); ctx.lineTo(X(A, p.x0), Y(A, p.dmin)); ctx.lineTo(X(A, Math.min(xc, 4)), Y(A, Math.min(p.dmin + p.dmax, 2.4))); ctx.lineTo(X(A, 4), Y(A, Math.min(p.dmin + p.dmax, 2.4))); ctx.stroke(); ctx.setLineDash([]);
  // the table
  ctx.fillStyle = mut; DATA.logE.forEach((x, i) => { ctx.beginPath(); ctx.arc(X(A, x), Y(A, DATA.curves[S.k][i]), 2, 0, 7); ctx.fill(); });
  line(A, (x) => f(x, p), ink, 1.6);
  // the inverse
  ctx.strokeStyle = red; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(X(A, -3), Y(A, S.yi)); ctx.lineTo(X(A, S.xi), Y(A, S.yi)); ctx.lineTo(X(A, S.xi), Y(A, 0)); ctx.stroke();
  ctx.fillStyle = red; ctx.beginPath(); ctx.arc(X(A, S.xi), Y(A, S.yi), 3, 0, 7); ctx.fill();
  ctx.textAlign = 'left'; ctx.fillText(`f⁻¹(${S.yi.toFixed(2)}) = ${S.xi.toFixed(3)}`.replace(/-/g, '−'), X(A, S.xi) + 6, Y(A, S.yi) - 6);
  // slope panel
  axes(B, [-2, 0, 2, 4], [0, 0.5, 1], 'log H', 'slope f′');
  ctx.strokeStyle = mut; ctx.lineWidth = 1; ctx.beginPath(); DATA.logE.forEach((x, i) => { if (!i) return; const s = (DATA.curves[S.k][i] - DATA.curves[S.k][i - 1]) / (x - DATA.logE[i - 1]), xm = 0.5 * (x + DATA.logE[i - 1]); i > 1 ? ctx.lineTo(X(B, xm), Y(B, Math.min(1, s))) : ctx.moveTo(X(B, xm), Y(B, Math.min(1, s))); }); ctx.stroke();
  line(B, (x) => df(x, p), ink, 1.6);
  ctx.fillStyle = red; ctx.beginPath(); ctx.arc(X(B, S.xi), Y(B, Math.min(1, S.si)), 3, 0, 7); ctx.fill();
  // readout
  ctx.fillStyle = ink; ctx.textAlign = 'left'; const L0 = 470; let yy = 196;
  const lines = [`layer ${'CMY'[S.k]} of Portra 400`, `rms against the table ${S.rms.toFixed(4)}`, `corners ${p.x0.toFixed(2)} and ${xc.toFixed(2)} log H`.replace(/-/g, '−'),
    `slope at the inverse ${S.si.toFixed(3)}`, `noise gain 1/f′ = ${(1 / S.si).toFixed(2)}`, `grey dots: table   black: fit`, `red dashed: the broken line`];
  lines.forEach((t, i) => { ctx.fillStyle = i >= 5 ? mut : ink; ctx.fillText(t, L0, yy + 16 * i); });
};

02-forward-model/dir-order.src:
// dir-order.js — interlayer (DIR) coupling applied before the curve, as spektrafilm's couplers.py does, against a
// density matrix applied after the curve and matched to the same effective gamma matrix at the grey card.
// before: d = f0(u − Mᵀ f(u)), f0 built so every neutral reproduces the datasheet; after: d = B f1(u), f1 = B⁻¹ f on
// neutrals, B chosen so B·diag(B⁻¹γ) = J_before(0). Parameters: the coupler amount (scales M), the green and blue
// exposure, the dye plotted. Try: green and blue at −1.5 (a dark red object), or amount 0. Data: spektrafilm (CC BY-SA 4.0).
