const PD = {"diag":[0.8015,0.8561,0.9087],"base":[0.1426,0.6438,0.759],"K":[[0.8015,0.0319,0.0072],[-0.0077,0.8561,0.0541],[0.0194,0.0523,0.9087]]};
const SHAPE = [0.888, 0.112, -1];   // per-layer log H shift per unit of cast (3,800 K: +0.166, +0.021, −0.187)
const lerp = (xs, ys, x) => { if (x <= xs[0]) return ys[0]; if (x >= xs[xs.length - 1]) return ys[ys.length - 1]; const i = Math.floor((x - xs[0]) / (xs[1] - xs[0])); const t = (x - xs[i]) / (xs[i + 1] - xs[i]); return ys[i] + t * (ys[i + 1] - ys[i]); };
const film = (k, x) => lerp(CURVES.x, CURVES.film[k], x), paper = (k, x) => lerp(CURVES.x, CURVES.paper[k], x);
const negPD = (logH) => { const c = [0, 1, 2].map((k) => film(k, logH[k])); return [0, 1, 2].map((k) => PD.base[k] + PD.K[k][0] * c[0] + PD.K[k][1] * c[1] + PD.K[k][2] * c[2]); };
const AIM = 0.745;                  // print density of an 18 % grey
const xFor = (k, target) => { let a = -2.5, b = 2.5; for (let i = 0; i < 50; i++) { const m = (a + b) / 2; if (paper(k, m) < target) a = m; else b = m; } return (a + b) / 2; };
const lightsFor = (pd) => [0, 1, 2].map((k) => xFor(k, AIM) + pd[k]);   // x_k = −PD_k + L_k hits the aim
const print = (logH, L, dD = [0, 0, 0]) => { const pd = negPD(logH); return [0, 1, 2].map((k) => Math.max(0, paper(k, -pd[k] + L[k]) + dD[k])); };
exports.setup = ({ params }) => {
  const shift = SHAPE.map((s) => s * params.cast), aimL = lightsFor(negPD([0, 0, 0]));
  const steps = []; for (let x = -2.5; x <= 2.501; x += 0.125) steps.push(+x.toFixed(3));
  const scene = (x) => [x, x, x], skin = [0.306, 0.08, -0.046];
  let L = aimL, dD = [0, 0, 0], pre = (h) => h.map((v, k) => v + shift[k]);
  if (params.mode === 'printer lights') L = lightsFor(negPD(pre([0, 0, 0])));
  if (params.mode === 'print density') { const g = print(pre([0, 0, 0]), aimL); dD = g.map((v) => AIM - v); }
  if (params.mode === 'film log H') pre = (h) => h;   // the cast removed before the film's curve: exact
  const row = (f) => steps.map((x) => ({ x, ref: print(scene(x), aimL), got: print(f(scene(x)), L, dD) }));
  return { rows: row(pre), skin: { ref: print(skin, aimL), got: print(pre(skin), L, dD) }, L, aimL, dD, shift };
};
exports.draw = (ctx, { w, h, params, state }) => {
  const INK = '#1a1a1a', GREY = '#737373', HAIR = '#d6d6d6', RED = '#e2001a';
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); ctx.font = '11px Arial';
  const rgb = (D) => 'rgb(' + D.map((d) => Math.round(255 * Math.pow(Math.min(1, Math.pow(10, -d) / Math.pow(10, -0.05)), 1 / 2.2))).join(',') + ')';
  // swatches: reference (no cast) and the corrected print, every other step
  const sx = 20, sy = 26, sw = 26; ctx.fillStyle = INK; ctx.textAlign = 'left';
  ctx.fillText('no cast', sx, sy - 6); ctx.fillText('cast, corrected by ' + params.mode, sx, sy + 46);
  state.rows.filter((_, i) => i % 4 === 0).forEach((r, i) => { ctx.fillStyle = rgb(r.ref); ctx.fillRect(sx + i * sw, sy, sw - 2, 30); ctx.fillStyle = rgb(r.got); ctx.fillRect(sx + i * sw, sy + 52, sw - 2, 30); ctx.fillStyle = GREY; ctx.textAlign = 'center'; ctx.fillText(String(r.x), sx + i * sw + sw / 2 - 1, sy + 96); });
  const kx = sx + 11 * sw + 10; ctx.fillStyle = rgb(state.skin.ref); ctx.fillRect(kx, sy, 40, 30); ctx.fillStyle = rgb(state.skin.got); ctx.fillRect(kx, sy + 52, 40, 30);
  ctx.fillStyle = GREY; ctx.fillText('skin', kx + 20, sy + 96); ctx.textAlign = 'left'; ctx.fillText('scene log H of each step', sx, sy + 110);
  // the colour of the grey scale: print density differences R − G and B − G against scene log H
  const gx = 50, gy = 160, gw = 330, gh = 160, lo = -0.4, hi = 0.4;
  const X = (x) => gx + (x + 2.5) / 5 * gw, Y = (v) => gy + gh - (Math.max(lo, Math.min(hi, v)) - lo) / (hi - lo) * gh;
  ctx.strokeStyle = GREY; ctx.lineWidth = 1; ctx.strokeRect(gx, gy, gw, gh);
  ctx.strokeStyle = HAIR; ctx.beginPath(); ctx.moveTo(gx, Y(0)); ctx.lineTo(gx + gw, Y(0)); ctx.stroke();
  ctx.fillStyle = GREY; ctx.textAlign = 'center'; for (const x of [-2, -1, 0, 1, 2]) ctx.fillText(String(x), X(x), gy + gh + 14);
  ctx.fillText('scene log exposure (grey card = 0)', gx + gw / 2, gy + gh + 28); ctx.textAlign = 'right'; for (const v of [-0.4, -0.2, 0, 0.2, 0.4]) ctx.fillText(v.toFixed(1), gx - 4, Y(v) + 4);
  const curve = (f, col, dash) => { ctx.strokeStyle = col; ctx.setLineDash(dash); ctx.lineWidth = 1.6; ctx.beginPath(); state.rows.forEach((r, i) => (i ? ctx.lineTo(X(r.x), Y(f(r))) : ctx.moveTo(X(r.x), Y(f(r))))); ctx.stroke(); ctx.setLineDash([]); };
  curve((r) => r.got[0] - r.got[1], INK, []); curve((r) => r.got[2] - r.got[1], INK, [4, 3]);
  curve((r) => r.ref[0] - r.ref[1], GREY, [1, 2]); curve((r) => r.ref[2] - r.ref[1], GREY, [1, 2]);
  ctx.fillStyle = INK; ctx.textAlign = 'left'; ctx.fillText('print density R − G (solid), B − G (dashed); no cast: dotted', gx, gy - 6);
  // readout
  let ty = 170; const tx = 400, line = (s, col = INK) => { ctx.fillStyle = col; ctx.fillText(s, tx, ty); ty += 16; };
  const err = (r) => Math.max(...[0, 1, 2].map((k) => Math.abs(r.got[k] - r.ref[k])));
  const worst = state.rows.reduce((a, r) => (err(r) > err(a) ? r : a));
  line('film log H shift: ' + state.shift.map((v) => (v >= 0 ? '+' : '') + v.toFixed(3)).join(' '));
  line('aim lights: ' + state.aimL.map((v) => v.toFixed(3)).join(' '), GREY);
  if (params.mode === 'printer lights') line('lights moved by: ' + state.L.map((v, k) => (v - state.aimL[k] >= 0 ? '+' : '') + (v - state.aimL[k]).toFixed(3)).join(' ') + ' log H', RED);
  if (params.mode === 'print density') line('density added to the print: ' + state.dD.map((v) => (v >= 0 ? '+' : '') + v.toFixed(3)).join(' '), RED);
  line('largest error on the scale: ' + err(worst).toFixed(3) + ' D at log H ' + worst.x.toFixed(2));
  line('paper white (log H +2.5): ' + err(state.rows[state.rows.length - 1]).toFixed(3) + ' D');
  line('skin: ' + Math.max(...[0, 1, 2].map((k) => Math.abs(state.skin.got[k] - state.skin.ref[k]))).toFixed(3) + ' D');
};

