exports.draw = (ctx, { w, h, params, state }) => {
  const INK = '#1a1a1a', GREY = '#737373', HAIR = '#d6d6d6', RED = '#e2001a';
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); ctx.font = '11px Arial'; ctx.lineJoin = 'round';
  const x0 = 50, y0 = 20, S = 300, { cmin, cmax, mmax, nx, ny } = state;
  const X = (c) => x0 + (c - cmin) / (cmax - cmin) * S, Y = (m) => y0 + S - m / mmax * S;
  ctx.fillStyle = '#f2f2f2'; ctx.fillRect(X(cmin), y0, X(0) - X(cmin), S);
  ctx.fillStyle = GREY; ctx.textAlign = 'center'; ctx.fillText('outside the box', (X(cmin) + X(0)) / 2, y0 + 14);
  // contours of log10 |r|
