  ctx.fillStyle = GREY; ctx.textAlign = 'center';
  for (const v of [-0.4, 0, 0.4, 0.8]) ctx.fillText(v.toFixed(1), X(v), y0 + S + 14);
  ctx.textAlign = 'right'; for (const v of [0, 0.4, 0.8, 1.2]) ctx.fillText(v.toFixed(1), x0 - 5, Y(v) + 4); ctx.textAlign = 'center';
  ctx.fillText('cyan dye amount', x0 + S / 2, y0 + S + 30);
  ctx.save(); ctx.translate(14, y0 + S / 2); ctx.rotate(-Math.PI / 2); ctx.fillText('magenta dye amount', 0, 0); ctx.restore();
  ctx.strokeStyle = INK; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(mmax)); ctx.stroke();
  ctx.fillStyle = INK; ctx.textAlign = 'left'; ctx.fillText('bound c_C = 0', X(0) + 6, Y(mmax) + 14);
  const styles = { gn: [GREY, [2, 3], 'Gauss–Newton'], lm: [INK, [], 'Levenberg–Marquardt'], active: [RED, [], 'active set'] };
  for (const k of ['gn', 'lm', 'active']) {
    if (!params[k]) continue; const [col, dash] = styles[k], p = state.paths[k];
    ctx.strokeStyle = col; ctx.fillStyle = col; ctx.setLineDash(dash); ctx.lineWidth = 1.6; ctx.beginPath();
    p.forEach((s, i) => { const px = X(Math.min(cmax, s.c[0])), py = Y(Math.min(mmax, s.c[1])); if (i) ctx.lineTo(px, py); else ctx.moveTo(px, py); }); ctx.stroke(); ctx.setLineDash([]);
    for (const s of p) { ctx.beginPath(); ctx.arc(X(Math.min(cmax, s.c[0])), Y(Math.min(mmax, s.c[1])), 2.2, 0, 7); ctx.fill(); }
  }
