  const GX = (i) => gx + i / it * gw, GY = (f) => gy + gh - (Math.max(lo, Math.log10(Math.max(1e-30, Math.sqrt(f) - state.best))) - lo) / (hi - lo) * gh;
  ctx.strokeStyle = GREY; ctx.lineWidth = 1; ctx.strokeRect(gx, gy, gw, gh); ctx.fillStyle = GREY; ctx.textAlign = 'right';
  for (const v of [0, -4, -8, -12]) ctx.fillText('1e' + v, gx - 4, gy + gh - (v - lo) / (hi - lo) * gh + 4);
  ctx.textAlign = 'center'; for (const v of [0, 25, 50]) ctx.fillText(String(v), GX(v), gy + gh + 14); ctx.fillText('iteration', gx + gw / 2, gy + gh + 28);
  ctx.textAlign = 'left'; ctx.fillText('excess |r| − best |r| (D)', gx, gy - 8);
  let ly = gy + gh + 50;
  for (const k of ['gn', 'lm', 'active']) {
    if (!params[k]) continue; const [col, dash, name] = styles[k], p = state.paths[k];
    ctx.strokeStyle = col; ctx.setLineDash(dash); ctx.lineWidth = 1.6; ctx.beginPath(); p.forEach((s, i) => (i ? ctx.lineTo(GX(i), GY(s.f)) : ctx.moveTo(GX(i), GY(s.f)))); ctx.stroke(); ctx.setLineDash([]);
