    ctx.fillText(name + ': ' + (p.length - 1) + ' it, |r| = ' + Math.sqrt(last.f).toExponential(3) + ' D', gx - 20, ly); ly += 14;
    ctx.fillText('   c = ' + last.c.map((v) => v.toFixed(3)).join(', '), gx - 20, ly); ly += 16;
  }
