// blur-cost.js — a separable Gaussian blur as the Studio's FS_BLUR computes it, against the exact blur.
// Model: a synthetic 192 × 128 test image; the blur truncated at R = ⌈kσ⌉ with renormalised weights (render.js
// blurKernel uses k = 3), optionally at half resolution (2 × 2 average, blur at σ/2, bilinear upsampling, as the
// Studio's bloom); the reference is the same blur truncated at 6σ at full resolution. Parameters: σ, k, half resolution.
// Readout: taps per pixel and relative cost (pixels × taps), and the error in 8-bit levels. Try k = 1.5, then half on.
exports.meta = {
  title: 'The cost and error of a separable blur', chapter: '4',
  about: 'Truncation radius and resolution against the exact Gaussian blur: taps, cost and error in 8-bit levels.',
  size: [640, 360],
  params: {
    sigma: { value: 6, min: 1, max: 16, step: 0.5, label: 'σ (pixels)' },
    k: { value: 3, min: 1, max: 4, step: 0.25, label: 'truncation k (R = ⌈kσ⌉)' },
    half: { value: false, label: 'blur at half resolution' },
  },
};
const INK = '#1a1a1a', MUT = '#737373', HAIR = '#d6d6d6', ACC = '#e2001a', W = 192, H = 128;
function mulberry32(a) { return () => { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function testImage() {
  const r = mulberry32(4), img = new Float32Array(W * H);
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    let v = 0.15 + 0.25 * x / W;
    if (x > 20 && x < 60 && y > 20 && y < 100) v = 0.85;                       // a bright bar
    if ((x - 120) ** 2 + (y - 50) ** 2 < 14 ** 2) v = 1.0;                       // a highlight
    if (x > 150 && x < 154) v = 0.9;                                             // a thin line
    if (y > 105 && x > 80 && x < 180) v = 0.05;                                  // a dark band
    img[y * W + x] = v + 0.02 * (r() - 0.5);
  }
  return img;
}
const SRC = testImage();
function blur1(src, w, h, sigma, R, horiz) {
  const k = []; let s = 0; for (let i = 0; i <= R; i++) { k.push(Math.exp(-0.5 * i * i / (sigma * sigma))); s += i ? 2 * k[i] : k[i]; }
  for (let i = 0; i <= R; i++) k[i] /= s;
  const out = new Float32Array(w * h), cl = (v, m) => (v < 0 ? 0 : v >= m ? m - 1 : v);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    let a = k[0] * src[y * w + x];
    for (let i = 1; i <= R; i++) a += k[i] * (horiz ? src[y * w + cl(x + i, w)] + src[y * w + cl(x - i, w)] : src[cl(y + i, h) * w + x] + src[cl(y - i, h) * w + x]);
    out[y * w + x] = a;
  }
  return out;
}
const blur = (src, w, h, sigma, R) => blur1(blur1(src, w, h, sigma, R, true), w, h, sigma, R, false);
exports.setup = ({ params }) => {
  const s = params.sigma, exact = blur(SRC, W, H, s, Math.ceil(6 * s));
  let fast, R, px;
  if (!params.half) { R = Math.max(1, Math.ceil(params.k * s)); fast = blur(SRC, W, H, s, R); px = W * H; }
  else {
    const w2 = W / 2, h2 = H / 2, lo = new Float32Array(w2 * h2);
    for (let y = 0; y < h2; y++) for (let x = 0; x < w2; x++) lo[y * w2 + x] = (SRC[2 * y * W + 2 * x] + SRC[2 * y * W + 2 * x + 1] + SRC[(2 * y + 1) * W + 2 * x] + SRC[(2 * y + 1) * W + 2 * x + 1]) / 4;
    R = Math.max(1, Math.ceil(params.k * s / 2)); const b = blur(lo, w2, h2, s / 2, R); px = w2 * h2;
    fast = new Float32Array(W * H);   // bilinear upsampling: full-size pixel centre (x+0.5)/2 − 0.5 in half-size texels
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const u = Math.min(w2 - 1, Math.max(0, (x + 0.5) / 2 - 0.5)), v = Math.min(h2 - 1, Math.max(0, (y + 0.5) / 2 - 0.5)), i = Math.min(w2 - 2, Math.floor(u)), j = Math.min(h2 - 2, Math.floor(v)), fu = u - i, fv = v - j;
      fast[y * W + x] = (b[j * w2 + i] * (1 - fu) + b[j * w2 + i + 1] * fu) * (1 - fv) + (b[(j + 1) * w2 + i] * (1 - fu) + b[(j + 1) * w2 + i + 1] * fu) * fv;
    }
