  for (let i = 0; i < W * H; i++) { const e = Math.abs(fast[i] - exact[i]) * 255; err[i] = e; mx = Math.max(mx, e); mean += e; }
  const Rf = Math.ceil(3 * s), costRef = W * H * 2 * (2 * Rf + 1), cost = px * 2 * (2 * R + 1);
  return { exact, fast, err, mx, mean: mean / (W * H), R, taps: 2 * (2 * R + 1), cost: cost / costRef, direct: (2 * Rf + 1) ** 2 / (2 * (2 * Rf + 1)) };
};
exports.draw = (ctx, { w, h, params, state: S }) => {
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); ctx.font = '11px Arial';
  const put = (arr, x0, y0, f) => { const im = ctx.createImageData(W, H); for (let i = 0; i < W * H; i++) { const c = f(arr[i]); im.data[4 * i] = c[0]; im.data[4 * i + 1] = c[1]; im.data[4 * i + 2] = c[2]; im.data[4 * i + 3] = 255; } ctx.putImageData(im, x0, y0); };
  const grey = (v) => { const g = Math.max(0, Math.min(255, Math.round(255 * v))); return [g, g, g]; };
  const red = (e) => { const t = Math.min(1, e / 4); return [255, Math.round(255 - t * 255), Math.round(255 - t * 229)]; };
  put(SRC, 16, 34, grey); put(S.fast, 224, 34, grey); put(S.err, 432, 34, red);
  ctx.strokeStyle = HAIR; for (const x of [16, 224, 432]) ctx.strokeRect(x - 0.5, 33.5, W + 1, H + 1);
  ctx.fillStyle = MUT; ctx.textAlign = 'left';
  ctx.fillText('input', 16, 26); ctx.fillText(`blurred, R = ${S.R}${params.half ? ' at half size' : ''}`, 224, 26); ctx.fillText('|error| against exact (red: 4 levels)', 432, 26);
  // a profile along row 50 (through the highlight): exact and fast, and the error ×20
  const y0 = 196, y1 = 300, X = (x) => 16 + x * (608 / (W - 1)), Y = (v) => y1 - v * (y1 - y0), row = 50;
  ctx.strokeStyle = MUT; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(16, y0); ctx.lineTo(16, y1); ctx.lineTo(624, y1); ctx.stroke();
  const line = (f, col, lw, dash) => { ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.setLineDash(dash); ctx.beginPath(); for (let x = 0; x < W; x++) { const yy = Y(f(x)); x ? ctx.lineTo(X(x), yy) : ctx.moveTo(X(x), yy); } ctx.stroke(); ctx.setLineDash([]); };
  line((x) => S.exact[row * W + x], INK, 1.6, []); line((x) => S.fast[row * W + x], ACC, 1.2, [5, 3]);
  line((x) => Math.min(1, 20 * Math.abs(S.fast[row * W + x] - S.exact[row * W + x])), MUT, 1, [1.5, 2.5]);
  ctx.fillStyle = MUT; ctx.fillText('row 50: exact (solid), this blur (red dashes), |difference| × 20 (dotted)', 16, y0 - 8);
  ctx.fillStyle = INK;
  ctx.fillText(`taps per pixel ${S.taps} (a direct 2-D kernel needs ${S.direct.toFixed(0)}× more at 3σ) · cost relative to full size at k = 3: ${S.cost.toFixed(2)}`, 16, 326);
  ctx.fillText(`error: max ${S.mx.toFixed(2)} levels, mean ${S.mean.toFixed(3)} levels in 255`, 16, 344);
};

04-making-it-fast/float32-solve.src:
// float32-solve.js — the dye solve of one table node in 64-bit floats (solve.js) and in 32-bit floats (the WGSL kernel
// of gpu.js, every operation rounded with Math.fround), with the history of the residual and of the projected gradient.
// Model: X-T5 + LED channels and Kodak Gold 200 dyes at 10 nm; d = K a + D_base; bounded LM with the active-set step,
