  const key = (i, d1, d2) => { const a = [0, 0, 0]; a[ax] = LO + i * h; a[oth[0]] = LO + (base[0] + d1) * h; a[oth[1]] = LO + (base[1] + d2) * h; return a; };
  const rows = [[0, 0], [1, 0], [0, 1], [1, 1]].map(([d1, d2]) => Array.from({ length: N }, (_, i) => solve(key(i, d1, d2)).c));
