  const V = (i, d) => { const o1 = d[oth[0]], o2 = d[oth[1]]; return rows[o1 + 2 * o2][i + d[ax]]; };
  const lookup = (i, t, tet) => { const f = [0, 0, 0]; f[ax] = t; f[oth[0]] = frac[0]; f[oth[1]] = frac[1];
    if (!tet) return [0, 1, 2].map((c) => { let v = 0; for (let q = 0; q < 8; q++) { const d = [q & 1, (q >> 1) & 1, (q >> 2) & 1]; v += d.reduce((w, dd, m) => w * (dd ? f[m] : 1 - f[m]), 1) * V(i, d)[c]; } return v; });
