    const ord = [0, 1, 2].sort((p, q) => f[q] - f[p]), d = [0, 0, 0], fs = [1, f[ord[0]], f[ord[1]], f[ord[2]], 0], out = [0, 0, 0];
    for (let s2 = 0; s2 < 4; s2++) { const w = fs[s2] - fs[s2 + 1], val = V(i, d); for (let c = 0; c < 3; c++) out[c] += w * val[c]; if (s2 < 3) d[ord[s2]] = 1; }
    return out; };
