    const v = LO + (HI - LO) * m / (M - 1), a = [0, 0, 0]; a[ax] = v; a[oth[0]] = fixed[0]; a[oth[1]] = fixed[1];
    const s = solve(a), u = (v - LO) / h, i = Math.min(N - 2, Math.floor(u)), t = u - i;
