exports.draw = (ctx, { w, h, params, state: S }) => {
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); ctx.font = '11px Arial'; ctx.lineWidth = 1;
  const x0 = 60, x1 = w - 20, X = (a) => x0 + (a - LO) / (HI - LO) * (x1 - x0);
  const panels = [[40, 160], [205, 325]];
  // unreachable wash
  ctx.fillStyle = 'rgba(226,0,26,0.08)'; S.xs.forEach((a, m) => { if (S.unreach[m]) ctx.fillRect(X(a) - 1.2, 40, 2.6, 285); });
  // top: dye amounts
  const [t0, t1] = panels[0], Y = (c) => t1 - c / 3 * (t1 - t0);
  ctx.strokeStyle = MUT; ctx.beginPath(); ctx.moveTo(x0, t0); ctx.lineTo(x0, t1); ctx.lineTo(x1, t1); ctx.stroke();
  ctx.fillStyle = MUT; ctx.textAlign = 'right'; for (const v of [0, 1, 2, 3]) { ctx.fillText(String(v), x0 - 6, Y(v) + 4); }
  ctx.textAlign = 'left'; ctx.fillText('dye amount c (exact solve); ticks: table nodes', x0, t0 - 8);
  const dashes = [[], [6, 3], [1.5, 3]], names = ['cyan', 'magenta', 'yellow'];
  for (let c = 0; c < 3; c++) { ctx.strokeStyle = INK; ctx.lineWidth = 1.6; ctx.setLineDash(dashes[c]); ctx.beginPath(); S.xs.forEach((a, m) => { const y = Y(Math.min(3, S.exact[m][c])); m ? ctx.lineTo(X(a), y) : ctx.moveTo(X(a), y); }); ctx.stroke(); ctx.setLineDash([]); ctx.fillStyle = INK; ctx.fillText(names[c], X(HI) - 50 - 50 * c, Y(Math.min(3, S.exact[S.xs.length - 1][c])) - 5); }
