  ctx.strokeStyle = MUT; ctx.beginPath(); ctx.moveTo(x0, b0); ctx.lineTo(x0, b1); ctx.lineTo(x1, b1); ctx.stroke();
  ctx.fillStyle = MUT; ctx.textAlign = 'right'; for (const e of [-6, -4, -2, 0]) ctx.fillText('1e' + e, x0 - 6, E(10 ** e) + 4);
  ctx.textAlign = 'center'; for (const a of [0, 0.5, 1, 1.5, 2, 2.5]) ctx.fillText(a.toFixed(1), X(a), b1 + 14);
  ctx.fillText(params.axis.replace(/ a(.)$/, ' key a$1') + '  (key a = K⁻¹ D, other two keys fixed)', (x0 + x1) / 2, b1 + 28);
  ctx.textAlign = 'left'; ctx.fillText('largest |c_table − c_exact| over the three dyes (grey: the other mode)', x0, b0 - 8);
  for (const [name, col, dash] of [[params.mode === 'trilinear' ? 'tetrahedral' : 'trilinear', MUT, [4, 3]], [params.mode, ACC, []]]) {
    ctx.strokeStyle = col; ctx.lineWidth = name === params.mode ? 1.6 : 1; ctx.setLineDash(dash); ctx.beginPath(); S.xs.forEach((a, m) => { const y = E(S.err[name][m]); m ? ctx.lineTo(X(a), y) : ctx.moveTo(X(a), y); }); ctx.stroke(); ctx.setLineDash([]);
  }
  ctx.fillStyle = INK; ctx.textAlign = 'right';
  ctx.fillText(`N ${S.N}, h ${S.h.toFixed(4)} · ${params.mode} · max error ${S.smooth(params.mode).toExponential(1)} in smooth cells, ${S.edge(params.mode).toExponential(1)} near the edge`, x1, 16);
  ctx.fillStyle = ACC; ctx.textAlign = 'left'; ctx.fillText('wash: residual ≥ 0.01 D', 8, 16);
};

