// tile-seams.js — a neighbourhood operation rendered in tiles, as render.js exportTiles does, against one pass.
// Model: a 240 × 120 synthetic image; a box blur of radius r computed tile by tile, each tile seeing only its own
// pixels plus a halo of h pixels (edges clamp, as a texture's do), and optionally a wide blur (σ = 16 px) that is either
// recomputed per tile or read from one global pass (the Studio's bases, halation and bloom). Parameters: tile size,
// halo, r, the wide field. Try: halo 0, then halo = r; then turn the wide field on per tile and globally.
exports.meta = {
  title: 'Tiles, halos and seams', chapter: '4',
  about: 'A blur rendered in tiles with and without a halo, against the one-pass result: the seam error and the cost of the halo.',
  size: [640, 360],
  params: {
    tile: { value: 60, min: 16, max: 120, step: 4, label: 'tile size (px)' },
    halo: { value: 0, min: 0, max: 12, step: 1, label: 'halo h (px)' },
    r: { value: 4, min: 1, max: 8, step: 1, label: 'blur radius r (px)' },
    wide: { value: 'off', options: ['off', 'per tile', 'global'], label: 'wide field (σ = 16)' },
  },
};
const INK = '#1a1a1a', MUT = '#737373', HAIR = '#d6d6d6', ACC = '#e2001a', W = 240, H = 120;
function mulberry32(a) { return () => { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const SRC = (() => { const r = mulberry32(11), a = new Float32Array(W * H); for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) { let v = 0.3 + 0.3 * Math.sin(x / 9) * Math.sin(y / 7); if ((x - 170) ** 2 + (y - 60) ** 2 < 30 ** 2) v = 0.95; if (x % 50 < 3) v = 0.05; a[y * W + x] = v + 0.06 * (r() - 0.5); } return a; })();
// blur of region [x0, x1) × [y0, y1) of src, edges clamped to the region (what a texture of that region would do)
function boxRegion(src, x0, y0, x1, y1, r) {
  const w = x1 - x0, h = y1 - y0, t = new Float32Array(w * h), o = new Float32Array(w * h), cl = (v, m) => (v < 0 ? 0 : v >= m ? m - 1 : v);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { let s = 0; for (let i = -r; i <= r; i++) s += src[(y0 + y) * W + x0 + cl(x + i, w)]; t[y * w + x] = s / (2 * r + 1); }
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { let s = 0; for (let i = -r; i <= r; i++) s += t[cl(y + i, h) * w + x]; o[y * w + x] = s / (2 * r + 1); }
  return o;
}
function gaussRegion(src, x0, y0, x1, y1, sigma) {   // three box passes of the same radius approximate a Gaussian
  const rr = Math.round((Math.sqrt(4 * sigma * sigma + 1) - 1) / 2), w = x1 - x0, h = y1 - y0; let cur = new Float32Array(W * H); cur.set(src);
  let reg = null; for (let k = 0; k < 3; k++) { reg = boxRegion(cur, x0, y0, x1, y1, rr); for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) cur[(y0 + y) * W + x0 + x] = reg[y * w + x]; }
  return reg;
}
function render(params, tiled) {
  const out = new Float32Array(W * H), T = tiled ? params.tile : Math.max(W, H), hh = tiled ? params.halo : 0;
  const global = params.wide === 'global' ? gaussRegion(SRC, 0, 0, W, H, 16) : null; let extra = 0;
  for (let ty = 0; ty < H; ty += T) for (let tx = 0; tx < W; tx += T) {
    const x0 = Math.max(0, tx - hh), y0 = Math.max(0, ty - hh), x1 = Math.min(W, tx + T + hh), y1 = Math.min(H, ty + T + hh), w = x1 - x0;
    const b = boxRegion(SRC, x0, y0, x1, y1, params.r), g = params.wide === 'per tile' ? gaussRegion(SRC, x0, y0, x1, y1, 16) : null;
    extra += (x1 - x0) * (y1 - y0);
    for (let y = ty; y < Math.min(H, ty + T); y++) for (let x = tx; x < Math.min(W, tx + T); x++) {
      let v = b[(y - y0) * w + (x - x0)];
      if (params.wide !== 'off') v = 0.6 * v + 0.6 * (g ? g[(y - y0) * w + (x - x0)] : global[y * W + x]) - 0.2;
      out[y * W + x] = v;
    }
  }
  return { out, extra: extra / (W * H) - 1 };
}
exports.setup = ({ params }) => {
  const one = render(params, false).out, t = render(params, true);
  let mx = 0, n = 0; const err = new Float32Array(W * H); for (let i = 0; i < W * H; i++) { err[i] = Math.abs(t.out[i] - one[i]) * 255; mx = Math.max(mx, err[i]); if (err[i] >= 0.5) n++; }
  return { tiled: t.out, err, mx, n, extra: t.extra };
};
exports.draw = (ctx, { w, h, params, state: S }) => {
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); ctx.font = '11px Arial';
  const put = (arr, x0, y0, f) => { const im = ctx.createImageData(W, H); for (let i = 0; i < W * H; i++) { const c = f(arr[i]); im.data[4 * i] = c[0]; im.data[4 * i + 1] = c[1]; im.data[4 * i + 2] = c[2]; im.data[4 * i + 3] = 255; } ctx.putImageData(im, x0, y0); };
  const grey = (v) => { const g = Math.max(0, Math.min(255, Math.round(255 * v))); return [g, g, g]; };
  const red = (e) => { const t = Math.min(1, e / 4); return [255, Math.round(255 - 255 * t), Math.round(255 - 229 * t)]; };
  put(S.tiled, 40, 40, grey); put(S.err, 360, 40, red);
  ctx.strokeStyle = HAIR; ctx.lineWidth = 1;
  for (const x0 of [40, 360]) { ctx.strokeRect(x0 - 0.5, 39.5, W + 1, H + 1); for (let t = params.tile; t < W; t += params.tile) { ctx.beginPath(); ctx.moveTo(x0 + t + 0.5, 40); ctx.lineTo(x0 + t + 0.5, 40 + H); ctx.stroke(); } for (let t = params.tile; t < H; t += params.tile) { ctx.beginPath(); ctx.moveTo(x0, 40 + t + 0.5); ctx.lineTo(x0 + W, 40 + t + 0.5); ctx.stroke(); } }
  ctx.fillStyle = MUT; ctx.textAlign = 'left'; ctx.fillText('rendered in tiles (grey lines: tile edges)', 40, 30); ctx.fillText('|tiled − one pass| (red: 4 levels in 255)', 360, 30);
  // the error along one row crossing tile edges
  const y0 = 196, y1 = 290, row = 60, X = (x) => 40 + x * (560 / (W - 1)), Y = (e) => y1 - Math.min(1, e / 8) * (y1 - y0);
  ctx.strokeStyle = MUT; ctx.beginPath(); ctx.moveTo(40, y0); ctx.lineTo(40, y1); ctx.lineTo(600, y1); ctx.stroke();
  ctx.fillStyle = MUT; ctx.textAlign = 'right'; for (const e of [0, 4, 8]) ctx.fillText(String(e), 34, Y(e) + 4); ctx.textAlign = 'left'; ctx.fillText('error along row 60 (levels)', 40, y0 - 8);
  ctx.strokeStyle = HAIR; for (let t = params.tile; t < W; t += params.tile) { ctx.beginPath(); ctx.moveTo(X(t - 0.5), y0); ctx.lineTo(X(t - 0.5), y1); ctx.stroke(); }
  ctx.strokeStyle = ACC; ctx.lineWidth = 1.6; ctx.beginPath(); for (let x = 0; x < W; x++) { const yy = Y(S.err[row * W + x]); x ? ctx.lineTo(X(x), yy) : ctx.moveTo(X(x), yy); } ctx.stroke();
  ctx.fillStyle = INK; ctx.textAlign = 'left';
  ctx.fillText(`tile ${params.tile} px, halo ${params.halo} px, blur radius ${params.r} px, wide field ${params.wide}`, 40, 316);
  ctx.fillText(`largest error ${S.mx.toFixed(2)} levels; ${S.n} pixels off by half a level or more; extra pixels computed for halos ${(100 * S.extra).toFixed(1)} %`, 40, 334);
  const why = params.wide === 'per tile' ? 'the wide field reads about 3σ = 48 px around each pixel, far beyond the halo' : params.halo >= params.r ? 'halo ≥ r: each tile sees every pixel its kernel reads' : 'halo < r: pixels near tile edges read clamped values';
  ctx.fillStyle = S.mx < 0.5 ? MUT : ACC; ctx.fillText(why, 40, 352);
};
